def transform(grid):
    # Find marker columns (columns with non-5 values)
    marker_cols = sorted(list(set(c for c in range(len(grid[0]))
                                   if any(grid[r][c] != 5 for r in range(len(grid))))))

    output_rows = []

    for r in range(len(grid)):
        first_marker = grid[r][marker_cols[0]]  # col 2
        is_shifted = (first_marker == 5)

        output = [7] * 5

        if is_shifted:
            # Shifted mode: output positions 1, 3
            output[1] = grid[r][marker_cols[1]]  # col 5
            output[3] = grid[r][marker_cols[3]]  # col 11
        else:
            # Normal mode: output positions 0, 2, 4
            # Map to pairs: (col2,col5), (col8,col11), (col14,col17)
            pairs = [(grid[r][marker_cols[0]], grid[r][marker_cols[1]]),
                     (grid[r][marker_cols[2]], grid[r][marker_cols[3]]),
                     (grid[r][marker_cols[4]], grid[r][marker_cols[5]])]
            for i, (v1, v2) in enumerate(pairs):
                if v1 == 5:
                    output[i*2] = v2 if v2 not in [5, 7] else 7
                elif v1 == v2 and v1 not in [5, 7]:
                    output[i*2] = v1
                else:
                    output[i*2] = 7

        output_rows.append(tuple(output))  # Use tuples for comparison

    # Deduplicate adjacent identical rows
    deduped = []
    for row in output_rows:
        if not deduped or row != deduped[-1]:
            deduped.append(row)

    # Convert back to list of lists
    return [list(r) for r in deduped]

